oxy_webhelp_navlinks = {"aws_rds-d39307e18932":{"topics":[{"title":"Amazon RDS reporting fields","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> derives capacity and identity fields for Amazon RDS databases         from AWS API data. Some field values differ from what the AWS Management console displays.         You must review these definitions to interpret reporting data correctly.<\/p>","href":"aws\/aws_rds_reporting_fields.html","attributes":{"data-id":"aws_rds_reporting_fields"},"menu":{"hasChildren":false},"tocID":"aws_rds_reporting_fields-d39307e18945","topics":[]},{"title":"Viewing the Amazon RDS database details page","shortdesc":"<p class=\"shortdesc\">To view information about an Amazon RDS database, access the database details         page.<\/p>","href":"saas\/aws_rds_view_database_details.html","attributes":{"data-id":"aws_rds_view_database_details"},"menu":{"hasChildren":false},"tocID":"aws_rds_view_database_details-d39307e18958","next":"aws_rds_view_database_details-d39307e18958"},{"title":"Snapshot types","shortdesc":"<p class=\"shortdesc\">To protect and manage your data in <span class=\"ph\">RSC<\/span>, based on your requirements,         you can take an on-demand snapshot, configure an SLA Domain to take scheduled snapshots and         continuous snapshots for point-in-time recovery (PITR), or both, and archived         snapshots.<\/p>","href":"saas\/aws_rds_snapshot_types.html","attributes":{"data-id":"aws_rds_snapshot_types"},"menu":{"hasChildren":false},"tocID":"aws_rds_snapshot_types-d39307e18980","next":"aws_rds_snapshot_types-d39307e18980"}]}};